// Composes the absolute signed URL for Azure. The URL exists ONLY inside this
// workflow, which persists no execution data. Any failure is re-raised REDACTED:
// a raw error would reach the parent's execution record (measured: 1 occurrence).
const inp = $('When Called by SW-005').first().json;
const res = $json || {};
const status = res.statusCode;
const body = res.body || {};

if (status !== 200 || !body.signedURL) {
  throw new Error('SW-030: signed-URL mint failed (HTTP ' + (status ?? 'n/a') +
    ') for key ' + (inp.storageKey || '(missing)') + ' [url redacted]');
}

const base = String($env.CRIE_STORAGE_ENDPOINT || '').replace(/\/+$/, '');
const rel  = String(body.signedURL).replace(/^\/+/, '');
const absolute = base + '/storage/v1/' + rel;

return [{ json: {
  urlSource: absolute,
  azureEndpoint: inp.azureEndpoint,
  azureModel: inp.azureModel,
  correlationId: inp.correlationId || null
} }];

// ISOLATION BOUNDARY. Returns ONLY the Azure submit response shape that SW-005's
// existing capture-pollUrl adapter already consumes: { statusCode, headers }.
// Nothing else crosses back — not the URL, not the request body, not the storage
// response, not Azure request metadata.
const res = $json || {};
const status = res.statusCode;

if (status === undefined || status === null) {
  // No response at all: re-raise REDACTED so nothing carrying the URL escapes.
  throw new Error('SW-030: Azure submit produced no response [url redacted]');
}

// Any real Azure status (including non-202) is returned as DATA so SW-005 keeps
// its existing routing: non-202 -> terminal submit failure -> OCR failed ->
// HUMAN_REVIEW. Headers are copied verbatim; they carry operation-location and
// retry-after, never the signed URL.
return [{ json: { statusCode: status, headers: res.headers || {} } }];
